// Remote OK API returns an array; first item is a legend/metadata object, skip it.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j || !j.id || !j.position) continue; // skip legend row
  out.push({
    json: {
      job_title: j.position || '',
      company: j.company || '',
      job_url: j.url || (j.id ? `https://remoteok.com/remote-jobs/${j.id}` : ''),
      source: 'Remote OK',
      location_text: j.location || 'Worldwide',
      salary: j.salary_min && j.salary_max ? `${j.salary_min}-${j.salary_max}` : (j.salary || ''),
      description: (j.description || '').replace(/<[^>]*>/g, ' ').trim(),
      posted_date: j.date || '',
      tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.tags || ''),
    },
  });
}
return out;

const first = $input.first();
const jobs = (first && first.json && first.json.jobs) ? first.json.jobs : [];
return jobs.map(j => ({
  json: {
    job_title: j.title || '',
    company: j.company_name || '',
    job_url: j.url || '',
    source: 'Remotive',
    location_text: j.candidate_required_location || 'Worldwide',
