    description: (j.description || '').replace(/<[^>]*>/g, ' ').trim(),
    posted_date: j.publication_date || '',
    tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.tags || ''),
  },
}));

return $input.all().map(item => {
  const j = item.json;
  const title = j.title || '';
  // WWR RSS titles are usually formatted "Company: Job Title"
  const parts = title.split(':');
  const company = parts.length > 1 ? parts[0].trim() : '';
  const jobTitle = parts.length > 1 ? parts.slice(1).join(':').trim() : title;
  return {
    json: {
      job_title: jobTitle,
      company: company,
      job_url: j.link || '',
      source: 'We Work Remotely',
      location_text: 'Worldwide',
      salary: '',
      description: (j.contentSnippet || j.content || j.summary || '').replace(/<[^>]*>/g, ' ').trim(),
      posted_date: j.pubDate || j.isoDate || '',
      tags: (j.categories || []).join(', '),
    },
  };
});

