const html = ($input.first() && $input.first().json && $input.first().json.data) || '';
const out = [];
try {
  const match = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
  if (match) {
    const data = JSON.parse(match[1]);
    const str = JSON.stringify(data);
    // Best-effort generic extraction; real selectors likely need adjusting per site.
    const jobsGuess = [];
    const walk = (node) => {
      if (!node || typeof node !== 'object') return;
      if (node.title && (node.url || node.slug) && (node.company || node.companyName)) {
        jobsGuess.push(node);
      }
      for (const k in node) walk(node[k]);
    };
    walk(data);
    for (const j of jobsGuess) {
      out.push({
        json: {
          job_title: j.title || '',
          company: j.company || j.companyName || '',
          job_url: j.url || j.slug || '',
          source: 'Wellfound',
          location_text: j.location || j.locationText || 'Unknown',
          salary: j.salary || '',
          description: j.description || j.excerpt || '',
          posted_date: j.postedDate || j.createdAt || '',
          tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
        },
      });
    }
  }
} catch (e) {
  // Parsing failed — site markup likely changed. Log and return nothing for this source.
  console.log('Wellfound scrape parse failed: ' + e.message);
}
return out;

