const SEARCH_KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'remote data analyst', 'remote data scientist',
  'remote ai marketing', 'remote marketing analyst', 'remote growth analyst',
  'remote bi analyst', 'remote automation specialist', 'remote ai workflow consultant',
];

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.job_url || !j.job_title) continue; // skip incomplete records
  const haystack = `${j.job_title} ${j.description} ${j.tags}`.toLowerCase();
  const matched = SEARCH_KEYWORDS.filter(k => haystack.includes(k));
  if (matched.length > 0) {
    out.push({ json: { ...j, matched_keywords: matched.join(', ') } });
  }
}
return out;

const existing = $('Get Existing Raw Jobs').all().map(i => i.json);
const seenUrls = new Set(existing.map(r => (r.job_url || '').trim().toLowerCase()).filter(Boolean));
const seenCompanyTitle = new Set(
  existing.map(r => `${(r.company || '').trim().toLowerCase()}|${(r.job_title || '').trim().toLowerCase()}`)
);

const out = [];
const seenThisRun = new Set();
for (const item of $input.all()) {
  const j = item.json;
  const url = (j.job_url || '').trim().toLowerCase();
  const companyTitleKey = `${(j.company || '').trim().toLowerCase()}|${(j.job_title || '').trim().toLowerCase()}`;

  if (url && seenUrls.has(url)) continue;
  if (!url && seenCompanyTitle.has(companyTitleKey)) continue;
  if (url && seenThisRun.has(url)) continue; // dedupe within this run's batch too
  if (!url && seenThisRun.has(companyTitleKey)) continue;

  seenThisRun.add(url || companyTitleKey);
  out.push(item);
}
return out;

function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(36);
}

const today = new Date().toISOString().slice(0, 10);
return $input.all().map(item => {
  const j = item.json;
  const idSource = j.job_url || `${j.company}|${j.job_title}`;
  return {
    json: {
      ...j,
      job_id: hashString(idSource),
      date_found: today,
    },
  };
});

const HARD_REJECT_PHRASES = [
  'us only', 'canada only', 'uk only', 'eu only', 'europe only', 'australia only',
  'must be based in', 'must live in', 'must be authorized to work in',
  'local work permit required', 'hybrid', 'onsite', 'office required',
  'remote within country only', 'fixed us hours', 'fixed eu hours',
];

const HARD_KEEP_PHRASES = [
  'worldwide remote', 'global remote', 'work from anywhere', 'anywhere', 'apac remote',
  'international contractors accepted', 'contractor role', 'b2b contractor',
  'hires via deel', 'hires via remote.com', 'hires via oyster', 'eor supported',
  'remote first', 'distributed team',
];

return $input.all().map(item => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.location_text} ${j.description}`.toLowerCase();

  const rejectHit = HARD_REJECT_PHRASES.find(p => haystack.includes(p));
  const keepHit = HARD_KEEP_PHRASES.find(p => haystack.includes(p));

  let hardFilterPass = true;
  let hardFilterReason = '';

  if (rejectHit) {
    hardFilterPass = false;
    hardFilterReason = `Keyword reject match: "${rejectHit}"`;
  } else if (!keepHit) {
    // No explicit reject phrase, but also no explicit worldwide/keep phrase —
    // send to the AI check as "unclear" rather than auto-rejecting.
    hardFilterReason = 'No explicit worldwide/keep phrase found — deferring to AI check';
  } else {
    hardFilterReason = `Keyword keep match: "${keepHit}"`;
  }

  return {
    json: {
      ...j,
      hardFilterPass,
      hardFilterReason,
      hardKeepHit: keepHit || '',
    },
  };
});

