return $input.all().map(item => {
  const j = item.json;
  let parsed = { taiwan_eligible: 'unclear', reason: 'AI parse failed', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
  try {
    const text = j.content && j.content[0] && j.content[0].text ? j.content[0].text : '';
    const match = text.match(/\{[\s\S]*\}/);
    if (match) parsed = JSON.parse(match[0]);
  } catch (e) {
    // keep the manual_check fallback above
  }
  return { json: { ...j, ...parsed } };
});

const ASYNC_REJECT = [
  'strict 9 to 5', 'fixed us hours', 'fixed est hours', 'fixed pst hours', 'fixed cet hours',
  'daily live calls required', 'must overlap full business day',
];

return $input.all().map(item => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.description}`.toLowerCase();

  const rejectHit = ASYNC_REJECT.find(p => haystack.includes(p));

  let asyncLevel = 'none';
  let asyncPoints = 0;

  if (rejectHit) {
    asyncLevel = 'reject';
    asyncPoints = 0;
  } else if (haystack.includes('async') || haystack.includes('asynchronous')) {
    asyncLevel = 'high';
    asyncPoints = 25;
  } else if (haystack.includes('flexible hours') || haystack.includes('flexible schedule')) {
    asyncLevel = 'medium';
    asyncPoints = 20;
  } else if (haystack.includes('distributed team') || haystack.includes('low meeting culture') || haystack.includes('work across time zones')) {
    asyncLevel = 'medium';
    asyncPoints = 15;
  } else if (haystack.includes('remote first')) {
    asyncLevel = 'low';
    asyncPoints = 10;
  }

  return {
    json: {
      ...j,
      async_level: asyncLevel,
      async_reject_hit: rejectHit || '',
      asyncPoints,
    },
  };
});

const CORE_ROLES = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence analyst', 'bi analyst', 'marketing analyst',
  'performance marketing analyst', 'growth analyst', 'ai marketing specialist',
  'ai automation specialist', 'ai workflow consultant', 'creative strategist with data',
  'martech analyst',
];

const ADJACENT_ROLES = [
  'marketing', 'analytics', 'automation', 'growth', 'seo', 'ppc', 'crm',
  'business intelligence', 'reporting', 'dashboard',
];

return $input.all().map(item => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.description}`.toLowerCase();

  const coreHit = CORE_ROLES.find(r => haystack.includes(r));
  const adjacentHit = ADJACENT_ROLES.find(r => haystack.includes(r));

  let roleCategory = 'unrelated';
  let rolePoints = 0;

  if (coreHit) {
    roleCategory = coreHit;
    rolePoints = 25;
  } else if (adjacentHit) {
    roleCategory = `adjacent: ${adjacentHit}`;
    rolePoints = 15;
  }

  return {
    json: {
      ...j,
      role_category: roleCategory,
      rolePoints,
    },
  };
});

const WORLDWIDE_PHRASES = [
  'worldwide remote', 'global remote', 'work from anywhere', 'anywhere',
  'international contractors accepted', 'contractor role', 'b2b contractor',
  'hires via deel', 'hires via remote.com', 'hires via oyster', 'eor supported',
];

return $input.all().map(item => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.location_text} ${j.description}`.toLowerCase();
  const hasWorldwide = WORLDWIDE_PHRASES.some(p => haystack.includes(p));
  const hasApac = haystack.includes('apac remote');

  // --- Taiwan eligibility points (tiered, take highest applicable) ---
  let taiwanPoints = 0;
  if (j.taiwan_eligible === 'no' || j.location_risk === 'high') {
    taiwanPoints = 0;
  } else if (j.taiwan_eligible === 'yes' && (hasWorldwide || j.contractor_possible === 'yes')) {
    taiwanPoints = 40;
  } else if (hasApac || (j.taiwan_eligible === 'yes' && j.location_risk === 'medium')) {
    taiwanPoints = 30;
  } else if (j.taiwan_eligible === 'unclear' && j.location_risk !== 'high') {
    taiwanPoints = 20;
  } else if (j.taiwan_eligible === 'yes') {
    taiwanPoints = 20;
  }

  // --- Async fit points already computed upstream (Async Filter node) ---
  const asyncPoints = j.asyncPoints || 0;

  // --- Role fit points already computed upstream (Role Fit node) ---
  const rolePoints = j.rolePoints || 0;

  // --- Salary fit points (tiered, take highest applicable) ---
  let salaryPoints = 0;
  const salaryNumbers = (j.salary || '').match(/\d[\d,]*/g);
  let maxSalary = 0;
  if (salaryNumbers) {
    maxSalary = Math.max(...salaryNumbers.map(n => parseInt(n.replace(/,/g, ''), 10)));
    // normalize likely-annual figures down to a monthly comparison baseline
    if (maxSalary > 20000) maxSalary = maxSalary / 12;
  }
  if (maxSalary > 5000) salaryPoints = 25;
  else if (maxSalary > 3000) salaryPoints = 15;
  else if (j.salary) salaryPoints = 10;

  let score = taiwanPoints + asyncPoints + rolePoints + salaryPoints;
  if (score > 100) score = 100;

  // --- One-sentence rule (step 15): hard gate regardless of computed score ---
  // "I can do this job while living in Taiwan, without moving, without foreign
  // work authorization, and without destroying my sleep schedule."
  const passesOneSentenceRule =
    j.taiwan_eligible !== 'no' &&
    j.location_risk !== 'high' &&
    j.async_level !== 'reject' &&
    j.timezone_risk !== 'high';

  if (!passesOneSentenceRule) {
    score = 0;
  }

  // --- Final decision logic (step 14) ---
  let decision = 'reject';
  let application_status = 'n/a';

  if (!passesOneSentenceRule || j.taiwan_eligible === 'no' || j.location_risk === 'high' || j.timezone_risk === 'high' || score < 70) {
    decision = 'reject';
    application_status = 'n/a';
  } else if (j.taiwan_eligible === 'unclear' && score >= 85 && j.location_risk === 'medium') {
    decision = 'manual_check';
    application_status = 'manual_check';
  } else if (
    j.taiwan_eligible === 'yes' &&
    score >= 85 &&
    ['high', 'medium'].includes(j.async_level) &&
    j.location_risk === 'low' &&
    ['low', 'medium'].includes(j.timezone_risk)
  ) {
    decision = 'keep';
    application_status = 'ready_to_apply';
  } else {
    decision = 'keep';
    application_status = 'review';
  }

  return {
    json: {
      ...j,
      score,
      taiwanPoints,
      asyncPoints,
      rolePoints,
      salaryPoints,
      passesOneSentenceRule,
      final_decision: decision,
      application_status,
      why_good_fit: `${j.role_category !== 'unrelated' ? `Role match: ${j.role_category}. ` : ''}${hasWorldwide ? 'Worldwide/anywhere remote. ' : ''}${j.async_level && j.async_level !== 'none' && j.async_level !== 'reject' ? `Async level: ${j.async_level}. ` : ''}${maxSalary ? `Est. monthly salary ~$${Math.round(maxSalary)}.` : ''}`.trim(),
    },
  };
});

const today = new Date().toISOString().slice(0, 10);
return $input.all().map(item => {
  const j = item.json;
  let reason = `Score ${j.score}/100 below threshold (70)`;
  if (j.taiwan_eligible === 'no') reason = `Taiwan eligibility: no — ${j.reason || ''}`;
  else if (j.location_risk === 'high') reason = `Location risk high — ${j.reason || ''}`;
  else if (j.timezone_risk === 'high') reason = `Timezone risk high — ${j.reason || ''}`;
  else if (j.async_level === 'reject') reason = `Async filter reject: ${j.async_reject_hit}`;
  return {
    json: {
      date_rejected: today,
      job_title: j.job_title,
      company: j.company,
      job_url: j.job_url,
      reason,
    },
  };
});

