return $input.all().map(item => {
  const j = item.json;
  let letter = '';
  try {
    letter = j.content && j.content[0] && j.content[0].text ? j.content[0].text.trim() : '';
  } catch (e) {
    letter = '';
  }
  return { json: { ...j, cover_letter_draft: letter } };
});

const today = new Date().toISOString().slice(0, 10);

const allFiltered = $('Get Today\'s Filtered Jobs').all().map(i => i.json);
const allRejected = $('Get Today\'s Rejected Jobs').all().map(i => i.json);

const todaysFiltered = allFiltered.filter(j => j.date_found === today);
const todaysRejected = allRejected.filter(j => j.date_rejected === today);

const topJobs = todaysFiltered
  .filter(j => j.decision === 'keep')
  .sort((a, b) => Number(b.score) - Number(a.score))
  .slice(0, 5);

const manualCheck = todaysFiltered.filter(
  j => j.taiwan_eligible === 'unclear' && Number(j.score) >= 70
);

function countReject(pattern) {
  return todaysRejected.filter(j => (j.reason || '').toLowerCase().includes(pattern)).length;
}

const rejectedUsOnly = countReject('us only');
const rejectedEuOnly = countReject('eu only') + countReject('europe only');
const rejectedHybrid = countReject('hybrid') + countReject('onsite') + countReject('office required');
const rejectedTimezone = countReject('timezone') + countReject('fixed us hours') + countReject('fixed eu hours');

let msg = `*Daily Taiwan Eligible Async Remote Jobs*\n_${today}_\n\n`;
msg += `*Top jobs today:*\n\n`;

if (topJobs.length === 0) {
  msg += `_No jobs cleared the score-70 bar today._\n\n`;
} else {
  topJobs.forEach((j, idx) => {
    msg += `${idx + 1}. *${j.job_title}*\n`;
    msg += `Company: ${j.company}\n`;
    msg += `Score: ${j.score}\n`;
    msg += `Taiwan eligible: ${j.taiwan_eligible}\n`;
    msg += `Reason: ${j.taiwan_reason}\n`;
    msg += `Async level: ${j.async_level}\n`;
    msg += `Timezone risk: ${j.timezone_risk}\n`;
    msg += `Salary: ${j.salary || 'Not listed'}\n`;
    msg += `Why it fits Jerry: ${j.why_good_fit}\n`;
    msg += `Apply link: ${j.job_url}\n\n`;
  });
}

msg += `*Manual check:*\n`;
if (manualCheck.length === 0) {
  msg += `_None today._\n\n`;
} else {
  manualCheck.forEach(j => {
    msg += `- ${j.job_title} @ ${j.company} (score ${j.score}) — ${j.job_url}\n`;
  });
  msg += `\n`;
}

msg += `*Rejected summary:*\n`;
msg += `US only: ${rejectedUsOnly}\n`;
msg += `EU/Europe only: ${rejectedEuOnly}\n`;
msg += `Hybrid/onsite: ${rejectedHybrid}\n`;
